package br.com.bemdoar.controller;
import br.com.bemdoar.dto.*;import br.com.bemdoar.enums.*;import br.com.bemdoar.security.UsuarioAutenticado;import br.com.bemdoar.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/doacoes")public class DoacaoController{private final DoacaoService s;public DoacaoController(DoacaoService s){this.s=s;}private Long uid(Authentication a){return ((UsuarioAutenticado)a.getPrincipal()).getId();}private boolean admin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMINISTRADOR"));}
 @PostMapping public ResponseEntity<DoacaoResponse> criar(Authentication a,@Valid @RequestBody DoacaoRequest q){return ResponseEntity.status(201).body(s.criar(uid(a),q));}@GetMapping("/minhas")public List<DoacaoResponse> minhas(Authentication a){return s.minhas(uid(a));}@GetMapping @PreAuthorize("hasRole('ADMINISTRADOR')")public List<DoacaoResponse> listar(@RequestParam(required=false)SituacaoDoacao situacao){return s.listar(situacao);}@GetMapping("/{id}")public DoacaoResponse buscar(@PathVariable Long id,Authentication a){return s.buscar(id,uid(a),admin(a));}@PatchMapping("/{id}/confirmar")@PreAuthorize("hasRole('ADMINISTRADOR')")public DoacaoResponse confirmar(@PathVariable Long id){return s.confirmar(id);}@PatchMapping("/{id}/receber")@PreAuthorize("hasRole('ADMINISTRADOR')")public DoacaoResponse receber(@PathVariable Long id){return s.receber(id);}@PatchMapping("/{id}/cancelar")public DoacaoResponse cancelar(@PathVariable Long id,@RequestBody(required=false)CancelamentoRequest q,Authentication a){return s.cancelar(id,uid(a),admin(a),q);}}
